Running command: cat > /workspace/test_harness.cpp << 'EOF'
#include <QBuffer>
#include <QImage>
#include <QImageIOHandler>
#include <cstdio>
#include <cstdlib>
#include <cstring>

// Forward declare the handler from the plugin
class RGBHandler : public QImageIOHandler
{
public:
    RGBHandler();
    bool canRead() const override;
    bool read(QImage *image) override;
    bool write(const QImage &image) override;
    static bool canRead(QIODevice *device);
};

int main(int argc, char *argv[])
{
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *data = new char[size];
    fread(data, 1, size, f);
    fclose(f);

    RGBHandler *handler = new RGBHandler();
    QImage i;
    QBuffer b;
    b.setData(QByteArray(data, size));
    b.open(QIODevice::ReadOnly);
    handler->setDevice(&b);
    handler->canRead();
    bool ok = handler->read(&i);
    fprintf(stderr, "read returned: %s\n", ok ? "true" : "false");
    delete handler;
    delete[] data;
    return 0;
}
EOF

